#include <stdio.h>

typedef struct { int peso, prioridade; } Encomenda;

long long passos(Encomenda *v, int n) {
    long long total = 0;
    for (int i = 0; i < n; i++) total += v[i].peso;
    if (n > 0) total += n - 1;
    return total;
}

int maisImportante(Encomenda *v, int n) {
    int melhor = -1;
    for (int i = 0; i < n; i++) {
        int substitui = melhor < 0
            || v[i].prioridade > v[melhor].prioridade
            || (v[i].prioridade == v[melhor].prioridade && v[i].peso < v[melhor].peso);
        if (substitui) melhor = i;
    }
    return melhor;
}

int main(void) {
    int n;
    char nome[64];
    scanf("%d", &n);
    Encomenda v[1024];
    for (int i = 0; i < n; i++) scanf("%63s %d %d", nome, &v[i].peso, &v[i].prioridade);
    printf("%lld\n", passos(v, n));
    int m = maisImportante(v, n);
    if (m < 0) printf("vazio\n");
    else printf("%d %d\n", v[m].peso, v[m].prioridade);
    return 0;
}

