def total_passos(pesos):
    return sum(pesos) + (len(pesos) - 1 if pesos else 0)

def mais_importante(encomendas):
    melhor = None
    for peso, prioridade in encomendas:
        if melhor is None or (prioridade, -peso) > (melhor[1], -melhor[0]):
            melhor = (peso, prioridade)
    return melhor

n = int(input())
encomendas = []
for _ in range(n):
    nome, peso, prioridade = input().split()
    encomendas.append((int(peso), int(prioridade)))
print(total_passos([p for p, _ in encomendas]))
melhor = mais_importante(encomendas)
