use std::io::{self, Read};

fn passos(pesos: &[i64]) -> i64 {
    let total: i64 = pesos.iter().sum();
    if pesos.is_empty() { 0 } else { total + pesos.len() as i64 - 1 }
}

fn mais_importante(encomendas: &[(i64, i64)]) -> Option<(i64, i64)> {
    let mut melhor: Option<(i64, i64)> = None;
    for &(peso, prioridade) in encomendas {
        let substitui = match melhor {
            None => true,
            Some((mp, mpr)) => prioridade > mpr || (prioridade == mpr && peso < mp),
        };
        if substitui {
            melhor = Some((peso, prioridade));
        }
    }
    melhor
}

fn main() {
    let mut entrada = String::new();
    io::stdin().read_to_string(&mut entrada).unwrap();
    let mut partes = entrada.split_whitespace();
    let n: usize = partes.next().unwrap().parse().unwrap();
    let mut encomendas: Vec<(i64, i64)> = Vec::new();
    for _ in 0..n {
        let _nome = partes.next().unwrap();
        let peso: i64 = partes.next().unwrap().parse().unwrap();
        let prioridade: i64 = partes.next().unwrap().parse().unwrap();
        encomendas.push((peso, prioridade));
    }
    let pesos: Vec<i64> = encomendas.iter().map(|e| e.0).collect();
    println!("{}", passos(&pesos));
    match mais_importante(&encomendas) {
        Some((peso, prioridade)) => println!("{} {}", peso, prioridade),
        None => println!("vazio"),
    }
}
